const e=["Dieu","Indulgence","Religion","Force"],s="Profite de ce que tu as. Mais n'oublie jamais que tu pourrais un jour ne plus pouvoir t'en passer.",n="Dieu de l’Indulgence",t=["Buklos représente l'Indulgence.","Il incarne le désir de profiter de la vie sans toujours penser aux conséquences.","La nourriture, les boissons, le repos, les richesses, les plaisirs, les fêtes ou simplement le confort peuvent tous relever de son domaine.","Buklos ne considère pas le plaisir comme une faiblesse.","Pour lui, une vie entièrement consacrée au sacrifice finit par oublier pourquoi elle mérite d'être vécue.","Mais l'indulgence possède une limite.","Lorsque le plaisir devient un besoin, il cesse d'être une liberté."],r=[{label:"Domaines",value:"Indulgence, Plaisir, Excès"},{label:"Symboles",value:"Une coupe remplie, une table abondante, des fruits, une couronne de fleurs, une pièce d'or, un coussin ou un fauteuil"}],i=[{title:"Le plaisir",title_border:"#e8553d",type:"text",content:["Les enseignements de Buklos encouragent à profiter des bonnes choses lorsqu'elles se présentent.","Une fête après une victoire.","Un repas partagé avec des amis.","Une nuit de repos après un long voyage.","Un cadeau que l'on s'offre après des années de travail.","Ces moments ont une valeur propre.","Ses fidèles considèrent souvent que refuser systématiquement le plaisir par culpabilité revient à mépriser la vie elle-même."]},{title:"L'excès",title_border:"#c2660a",type:"text",content:["L'autre visage de Buklos apparaît lorsque l'indulgence devient incontrôlable.","Un banquet peut devenir une dépendance.","La richesse peut devenir une obsession.","Le repos peut devenir de la paresse.","Le plaisir peut devenir une prison.","Buklos ne prétend pas que cette frontière est facile à déterminer.","C'est justement ce qui rend son domaine dangereux."]},{title:"Le culte de Buklos",title_border:"#6f9fd8",type:"text",content:["Les temples de Buklos sont rarement austères.","Ils peuvent prendre la forme de tavernes, de jardins, de grandes salles de banquet ou de lieux de rassemblement.","Ses prêtres organisent souvent des fêtes et des repas communautaires.","Ils peuvent également être appelés lors de célébrations importantes : mariages, victoires, naissances ou grandes retrouvailles.","Mais certains cultes plus secrets sont associés aux plaisirs les plus extrêmes.","Ces groupes sont généralement considérés avec méfiance par les autres religions."]},{title:"Buklos et Metona",title_border:"#e8553d",type:"text",content:["Buklos entretient une relation naturelle avec Metona.","L'Amour et l'Indulgence se rencontrent souvent dans les plaisirs partagés.","Un repas avec sa famille, une fête entre amis ou un moment de repos avec ceux que l'on aime peuvent être considérés comme des expressions des deux Forces.","Mais Metona rappelle que le plaisir ne doit pas devenir une possession.","Buklos rappelle, lui, que l'amour de soi et le droit au plaisir ne doivent pas être oubliés."]},{title:"Buklos et Phiella",title_border:"#c2660a",type:"text",content:["Phiella et Buklos sont parfois associés.","La Tentation peut pousser un individu vers l'Indulgence, tandis que l'Indulgence peut devenir une nouvelle source de tentation.","Pourtant, leurs domaines restent différents.","Phiella concerne le choix face au désir.","Buklos concerne le fait de céder au désir."]},{title:"Symboles",title_border:"#6f9fd8",type:"text",content:"Buklos est généralement représenté par :"},{title:"",type:"list",content:["Une coupe remplie","Une table abondante","Des fruits","Une couronne de fleurs","Une pièce d'or","Un coussin ou un fauteuil"]},{title:"",type:"text",content:["La coupe est son symbole le plus courant.","Une coupe pleine représente le plaisir disponible.","Une coupe débordante représente l'excès."]},{title:"Aujourd'hui",title_border:"#e8553d",type:"text",content:["Buklos est rarement considéré comme une divinité dangereuse par ceux qui le vénèrent.","C'est justement ce qui rend son enseignement difficile.","Il est facile de savoir quand un plaisir devient excessif chez quelqu'un d'autre.","Il est beaucoup plus difficile de reconnaître le moment où cela devient vrai pour soi-même."]}],o=["Les Dieux","Les Forces","Metona","Phiella","La Tentation","L’Amour"],l={tags:e,citation:s,surname:n,presentation:t,infos:r,sections:i,related:o};export{s as citation,l as default,r as infos,t as presentation,o as related,i as sections,n as surname,e as tags};
